// Zentrale Terminregeln. Betriebsspezifische Werte kommen aus betrieb.termin
// (Hauptworkflow → Betriebskonfiguration) und überschreiben diese Standards.
const STANDARD = {
  modus: 'test',                       // test | vorschlagen | automatisch_buchen
  zeitzone: 'Europe/Berlin',           // Anzeige; gespeichert wird immer UTC
  kalender: { anbieter: 'test', ressource_id: 'team-1', outlook: { postfach: '', kalender_id: '' } },
  oeffnungszeiten: [
    { tage: [1, 2, 3, 4], von: '08:00', bis: '17:00' },   // 1 = Montag … 7 = Sonntag
    { tage: [5], von: '08:00', bis: '14:00' }
  ],
  pausen: [{ von: '12:00', bis: '12:30' }],
  gesperrte_tage: [],                  // ['2026-12-24', …] (lokales Datum)
  gesperrte_zeitraeume: [],            // [{ von: '2026-10-05T08:00', bis: '2026-10-09T17:00', grund: 'Urlaub' }] (lokale Zeit)
  fruehester_termin_stunden: 24,
  horizont_tage: 14,
  raster_minuten: 30,
  puffer_vor_minuten: 15,
  puffer_nach_minuten: 15,
  max_termine_pro_tag: 4,
  anzahl_vorschlaege: 3,
  ein_vorschlag_pro_tag: true,
  vorschlag_gueltig_stunden: 48,
  max_vorschlagsrunden: 2,             // danach Wunschzeitraum erfragen + Mitarbeiteraufgabe
  reservierung_ablauf_minuten: 10,     // ältere, nicht gebuchte Reservierungen gelten als abgelaufen
  einsatzgebiet: { plz: [], orte: [] }, // PLZ oder PLZ-Präfixe, Ortsnamen
  erlaubte_dringlichkeiten: ['niedrig', 'normal'],
  fehlende_angaben_blockieren: true,
  vorabpruefung_stichworte: ['ersatzteil', 'sonderanfertigung', 'gutachten', 'dichtheitsprüfung', 'druckprüfung', 'abgasmessung', 'schornstein', 'asbest', 'elektroanschluss', 'starkstrom', 'kältemittel', 'kaeltemittel'],
  terminarten: {
    wartung: { bezeichnung: 'Wartung', automatisch: true, dauer_minuten: 90, stichworte: ['wartung', 'inspektion', 'jahreswartung'], kategorien: ['Wartung'] },
    reparatur_planbar: { bezeichnung: 'planbare Reparatur', automatisch: true, dauer_minuten: 120, stichworte: ['reparatur', 'reparieren', 'tropft', 'austauschen', 'tauschen', 'erneuern'], kategorien: [] },
    beratung_besichtigung: { bezeichnung: 'Beratung/Besichtigung vor Ort', automatisch: true, dauer_minuten: 60, stichworte: ['beratung', 'besichtigung', 'beraten', 'vor ort anschauen'], kategorien: ['Neuinstallation'] },
    heizkoerper_thermostat: { bezeichnung: 'Heizkörper/Thermostat', automatisch: true, dauer_minuten: 60, stichworte: ['heizkörper', 'heizkoerper', 'thermostat', 'entlüften', 'entlueften'], kategorien: [] },
    angebot_grossauftrag: { bezeichnung: 'Angebot/Großauftrag', automatisch: false, dauer_minuten: null, stichworte: ['angebot', 'kostenvoranschlag', 'sanierung', 'badumbau', 'neue heizung', 'wärmepumpe', 'waermepumpe', 'komplett erneuern'], kategorien: ['Angebotsanfrage'] }
  }
};

const eingang = $input.first().json;
const istObjekt = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const mischen = (basis, extra) => {
  if (!istObjekt(extra)) return basis;
  const out = Object.assign({}, basis);
  for (const [k, v] of Object.entries(extra)) out[k] = istObjekt(v) && istObjekt(basis[k]) ? mischen(basis[k], v) : v;
  return out;
};
const betrieb = istObjekt(eingang.betrieb) ? eingang.betrieb : {};
const cfg = mischen(STANDARD, betrieb.termin);

const fehler = [];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const HHMM = /^([01]\d|2[0-3]):[0-5]\d$/;
if (!UUID.test(String(betrieb.betrieb_id || ''))) fehler.push('betrieb_id fehlt oder ist ungültig');
if (!/^https:\/\/[^\s/]+/.test(String(betrieb.supabase_url || ''))) fehler.push('supabase_url fehlt oder ist ungültig');
if (!['test', 'vorschlagen', 'automatisch_buchen'].includes(cfg.modus)) fehler.push('modus ungültig');
if (!istObjekt(cfg.kalender) || !['test', 'outlook'].includes(cfg.kalender.anbieter)) fehler.push('kalender.anbieter ungültig');
else {
  if (!String(cfg.kalender.ressource_id || '').trim()) fehler.push('kalender.ressource_id fehlt');
  if (cfg.kalender.anbieter === 'outlook' && !String((cfg.kalender.outlook || {}).postfach || '').includes('@')) fehler.push('kalender.outlook.postfach fehlt');
}
if (!DateTime.now().setZone(String(cfg.zeitzone)).isValid) fehler.push('zeitzone ungültig');
const zahl = (k, min, max) => { const v = Number(cfg[k]); if (!Number.isFinite(v) || v < min || v > max) fehler.push(k + ' ungültig'); };
zahl('fruehester_termin_stunden', 0, 720); zahl('horizont_tage', 1, 90); zahl('raster_minuten', 5, 240);
zahl('puffer_vor_minuten', 0, 240); zahl('puffer_nach_minuten', 0, 240); zahl('max_termine_pro_tag', 1, 50);
zahl('anzahl_vorschlaege', 1, 5); zahl('vorschlag_gueltig_stunden', 1, 720);
zahl('max_vorschlagsrunden', 1, 5); zahl('reservierung_ablauf_minuten', 5, 120);
if (!Array.isArray(cfg.oeffnungszeiten) || !cfg.oeffnungszeiten.length) fehler.push('oeffnungszeiten fehlen');
else cfg.oeffnungszeiten.forEach((f, i) => {
  if (!Array.isArray(f.tage) || !f.tage.every(t => Number.isInteger(t) && t >= 1 && t <= 7) || !HHMM.test(f.von) || !HHMM.test(f.bis) || f.von >= f.bis) fehler.push('oeffnungszeiten[' + i + '] ungültig');
});
(Array.isArray(cfg.pausen) ? cfg.pausen : []).forEach((p, i) => { if (!HHMM.test(p.von) || !HHMM.test(p.bis) || p.von >= p.bis) fehler.push('pausen[' + i + '] ungültig'); });
(Array.isArray(cfg.gesperrte_zeitraeume) ? cfg.gesperrte_zeitraeume : []).forEach((z, i) => {
  const v = DateTime.fromISO(String(z.von), { zone: cfg.zeitzone }); const b = DateTime.fromISO(String(z.bis), { zone: cfg.zeitzone });
  if (!v.isValid || !b.isValid || b <= v) fehler.push('gesperrte_zeitraeume[' + i + '] ungültig');
});
if (!istObjekt(cfg.terminarten)) fehler.push('terminarten fehlen');
if (fehler.length) throw new Error('Terminkonfiguration ungültig: ' + fehler.join('; '));

// Testuhr und Testkalender-Daten nur mit dem Testkalender – nie mit einem echten Kalender.
// Quelle: Aufruf (test) oder Testkonfiguration des Betriebs (termin.test).
const testQuelle = istObjekt(eingang.test) ? eingang.test : (istObjekt(cfg.test) ? cfg.test : {});
const test = cfg.kalender.anbieter === 'test' ? testQuelle : {};
let jetzt = DateTime.utc();
if (test.jetzt_utc) {
  jetzt = DateTime.fromISO(String(test.jetzt_utc), { zone: 'utc' });
  if (!jetzt.isValid) throw new Error('test.jetzt_utc ungültig');
}

const aktion = String(eingang.aktion || '').trim();
const anfrage = istObjekt(eingang.anfrage) ? eingang.anfrage : {};
const basis = {
  aktion,
  kanal: String(eingang.kanal || '').trim() || 'unbekannt',
  betrieb_id: betrieb.betrieb_id,
  supabase_url: String(betrieb.supabase_url).replace(/\/+$/, ''),
  cfg,
  anfrage,
  kunden_nachricht: String(eingang.kunden_nachricht || '').slice(0, 1000),
  wunsch: istObjekt(eingang.wunsch) ? eingang.wunsch : {},
  test,
  jetzt_utc: jetzt.toISO(),
  zeitraum: { von_utc: jetzt.minus({ days: 1 }).toISO(), bis_utc: jetzt.plus({ days: Number(cfg.horizont_tage) + 2 }).toISO() }
};

// Aktionen: vorschlagen, bestaetigen, kundenantwort (kanalneutral), anzeigen, verschieben, stornieren,
// verfuegbarkeit (nur lesen, z. B. Telefon) und direkt_buchen (ausdrücklich bestätigter Wunschtermin).
const MIT_ID = ['bestaetigen', 'kundenantwort', 'anzeigen', 'verschieben', 'stornieren', 'direkt_buchen'];
const idOk = UUID.test(String(anfrage.anfrage_db_id || ''));
if (aktion === 'verfuegbarkeit') return [{ json: Object.assign({}, basis, { weiter: 'eignung_pruefen' }) }];
if (aktion === 'vorschlagen') return [{ json: Object.assign({}, basis, { weiter: idOk ? 'terminwahl_lesen' : 'eignung_pruefen' }) }];
if (MIT_ID.includes(aktion)) {
  if (!idOk) {
    return [{ json: Object.assign({}, basis, { weiter: 'mitarbeiter', mitarbeiter: { aufgabe_anlegen: false, termin_status: null, gruende: ['Anfrage-ID fehlt – Terminvorgang nicht zuordenbar'], kunden_nachricht: '' } }) }];
  }
  if (aktion === 'direkt_buchen' && !DateTime.fromISO(String(basis.wunsch.start_utc || ''), { zone: 'utc' }).isValid) {
    return [{ json: Object.assign({}, basis, { weiter: 'antwort', antwort: { ergebnis: 'ungueltig', gruende: ['Wunschtermin fehlt oder ist ungültig'] } }) }];
  }
  return [{ json: Object.assign({}, basis, { weiter: 'terminwahl_lesen' }) }];
}
return [{ json: Object.assign({}, basis, { weiter: 'antwort', antwort: { ergebnis: 'fehler', gruende: ['Unbekannte Aktion „' + aktion + '“'] } }) }];

const K = $('Terminkonfiguration').first().json;
const cfg = K.cfg;
const a = K.anfrage || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const anfrageOk = UUID.test(String(a.anfrage_db_id || ''));
const TEXT_PERSOENLICH = 'Vielen Dank für Ihre Rückmeldung. Ihren Termin stimmt unser Serviceteam persönlich mit Ihnen ab.';

// Regelbasierte Prüfung: nur eindeutig planbare Standardfälle werden automatisch terminiert.
const t = v => String(v ?? '').trim();
const W = $('Terminwahl erkennen').isExecuted ? $('Terminwahl erkennen').first().json : null;
const aktion = W && W.aktion ? W.aktion : K.aktion;
const gewaehlt = W && W.gewaehlt ? W.gewaehlt : null;
const verschiebung = W && W.verschiebung ? W.verschiebung : null;
const anliegen = t(a.technisches_anliegen);
const anliegenText = (t(a.kategorie) + ' ' + anliegen).toLowerCase();
const gesamt = (anliegenText + ' ' + t(K.kunden_nachricht)).toLowerCase();
const gruende = [];
let notfall = false;

if (!anfrageOk && aktion !== 'verfuegbarkeit') gruende.push('Anfrage-ID fehlt – Termin nicht zuordenbar');

// Jede Gefahrenart wird getrennt als vorhanden, verneint oder unklar bewertet.
// Eine Verneinung wirkt nur in ihrem eigenen Teilsatz; "Gas nicht abstellbar" bleibt Notfall.
function gefahrenlage(roh){const N=String(roh||'').toLowerCase().replace(/ä/g,'ae').replace(/ö/g,'oe').replace(/ü/g,'ue').replace(/ß/g,'ss').replace(/\s+/g,' ').trim();const Z={gas:'nicht_erwaehnt',wasser:'nicht_erwaehnt',brand:'nicht_erwaehnt',strom:'nicht_erwaehnt',dringend:'nicht_erwaehnt',versorgung:'nicht_erwaehnt'};const B=[];if(N){const T=N.split(/[.!?;:\n]+|,| und | sowie | aber | jedoch | allerdings | dennoch | sondern | trotzdem | doch /).map(s=>s.trim()).filter(Boolean);const I={gas:/gasgeruch|gasaustritt|gasleck|gasverlust|\bgas\b|kohlenmonoxid|\bco[- ]?(melder|warner)\b|propan|fluessiggas|(gasleitung|gasrohr|gashahn|gastherme)\s+(\w+\s+){0,3}(zischt|undicht|leckt|riecht|offen)|(zischt|riecht|pfeift)\s+(\w+\s+){0,4}(gasleitung|gasrohr|gashahn)/,wasser:/wasseraustritt|wasserschaden|rohrbruch|ueberschwemm|ueberflut|\bleck\b|leckage|undicht|wasser im keller|pfuetze|(rohr|leitung|schlauch|ventil|therme|boiler|speicher|heizung)\s+(\w+\s+){0,2}(geplatzt|gebrochen|gerissen|undicht|laeuft aus)|\bwasser\b\s*(\w+\s+){0,2}(tritt|laeuft|spritzt|stroemt|sprudelt|steht|dringt)|(tritt|laeuft|spritzt|stroemt|sprudelt|steht|dringt)\s+(\w+\s+){0,3}\bwasser\b|(nasse|nasser|nasses|feuchte|feuchter|feuchtes)\s+(wand|waende|decke|boden|keller)|(wand|waende|decke|boden|keller|teppich|estrich)\s+(\w+\s+){0,3}(feucht|nass|durchnaesst)/,brand:/brandgeruch|\brauch\b|rauchmelder|qualm|verbrannt|verschmort|schmor|\bfeuer\b|\bbrennt\b|\bbrand\b|funken|russ/,strom:/stromschlag|kurzschluss|kabelbrand|elektrischer schlag/};const D=/\bnotfall\b|\bdringend\b|\bsofort\b|\beilt\b|so schnell wie moeglich|\bakut\b|\bumgehend\b/;const V=/kein(e|en)? (heizung|warmwasser|warmes wasser)|(heizung|warmwasser) (ist |faellt )?(komplett )?(ausgefallen|aus)\b|heizung geht nicht|warmwasser (geht|funktioniert) nicht/;const NEG=/^(kein|keine|keinen|keiner|keinem|keines|keinerlei|nicht|nichts|nie|niemals|ohne|weder|noch|frei|unauffaellig|negativ|trocken|dicht)$/;const U=/vielleicht|moeglicherweise|eventuell|\bevtl\b|unsicher|unklar|weiss (ich )?nicht|keine ahnung|kann ich nicht sagen|nicht sicher|ob (es|da|dort|irgendwo)|schwer zu sagen/;const H=/(nicht|nichts|niemand)\s+(\w+\s+){0,3}(abstellen|abdrehen|zudrehen|absperren|abschalten|ausschalten|stoppen|schliessen|loeschen|erreichen|finden|beheben|stillen|aufhalten)|(abstellen|abdrehen|zudrehen|absperren|abschalten|ausschalten|stoppen|schliessen|loeschen|erreichen|finden|beheben|stillen|aufhalten)\s+(\w+\s+){0,2}nicht\b/;const TR=/(leitung|rohr|boden|waende|wand|decke|keller|stelle|alles|es|hier|dort)\s+(ist |sind |bleibt |war |scheint |wirkt )?(komplett |voellig |ganz |wieder )?(trocken|dicht)\b/;const R={nicht_erwaehnt:0,verneint:1,unklar:2,vorhanden:3};const setze=(art,wert,teil)=>{if(R[wert]>R[Z[art]]){Z[art]=wert;B.push(art+': '+wert+' ('+teil.slice(0,60)+')');}};const bewerte=(teil,tr)=>{if(H.test(teil))return 'vorhanden';if(U.test(teil))return 'unklar';const w=teil.split(' ');const i=teil.slice(0,tr.index).split(' ').length-1;const L=String(tr[0]||'').split(' ').length;for(let j=Math.max(0,i-4);j<Math.min(w.length,i+L+4);j++){if(NEG.test(String(w[j]||'').replace(/[^a-z]/g,'')))return 'verneint';}return 'vorhanden';};for(const teil of T){for(const art of ['gas','wasser','brand','strom']){const tr=I[art].exec(teil);if(tr)setze(art,bewerte(teil,tr),teil);}if(TR.test(teil)&&Z.wasser==='nicht_erwaehnt')setze('wasser','verneint',teil);const d=D.exec(teil);if(d)setze('dringend',bewerte(teil,d),teil);if(V.test(teil))setze('versorgung','vorhanden',teil);}}const arten=['gas','wasser','brand','strom'];const vor=arten.filter(a=>Z[a]==='vorhanden');const notfall=vor.length>0||Z.dringend==='vorhanden'||Z.versorgung==='vorhanden';return{gas:Z.gas,wasser:Z.wasser,brand:Z.brand,strom:Z.strom,dringend:Z.dringend,versorgung:Z.versorgung,notfall:notfall,unklar:arten.some(a=>Z[a]==='unklar'),notfall_art:vor.indexOf('gas')>=0?'gas':(vor.indexOf('wasser')>=0?'wasser':(notfall?'sonstig':'')),begruendung:B};}

const uebergeben = (a.gefahren && typeof a.gefahren === 'object' && a.gefahren.gas_gefahr) ? a.gefahren : null;
const G = uebergeben
  ? { gas: uebergeben.gas_gefahr, wasser: uebergeben.wasser_gefahr, brand: uebergeben.brand_gefahr, strom: uebergeben.strom_gefahr, dringend: uebergeben.dringend, versorgung: uebergeben.versorgung_ausfall, unklar: uebergeben.unklar === true }
  : gefahrenlage(gesamt);
const dring = t(a.dringlichkeit).toLowerCase() || 'normal';

if (G.gas === 'vorhanden') { gruende.push('Verdacht auf Gas oder CO – Notfall, nur durch Mitarbeiter'); notfall = true; }
if (G.wasser === 'vorhanden' || (t(a.kategorie) === 'Wasserschaden' && G.wasser !== 'verneint')) { gruende.push('Wasseraustritt oder Rohrbruch – Notfall, nur durch Mitarbeiter'); notfall = true; }
if (G.brand === 'vorhanden' || G.strom === 'vorhanden') { gruende.push('Brand-, Rauch- oder Stromgefahr – Notfall, nur durch Mitarbeiter'); notfall = true; }
if (dring === 'notfall' || a.notfall === true || G.dringend === 'vorhanden' || G.versorgung === 'vorhanden') { gruende.push('Notfall oder dringend beschrieben'); notfall = true; }
else if (!(cfg.erlaubte_dringlichkeiten || []).includes(dring)) gruende.push('Dringlichkeit „' + dring + '“ ist nicht für automatische Termine freigegeben');
if (G.unklar === true) gruende.push('Mögliche Gefahr sprachlich unklar – zur Sicherheit Mitarbeiterprüfung');

if (anliegen.length < 15 || /KI-Analyse nicht verfügbar|keine strukturierten Anrufdaten/i.test(anliegen)) gruende.push('Anliegen unklar oder zu kurz');

// Für erste Terminvorschläge sind Wunschtermin, Uhrzeit, Gerätemodell, Baujahr, Fehlercode,
// Hersteller, Warmwasserstatus oder ein zusätzlicher Ansprechpartner nicht erforderlich.
// Adresse, PLZ und Telefonnummer werden unten eigenständig geprüft. Blockierend sind nur
// Angaben, ohne die der Einsatz selbst unklar bleibt (z. B. Zugang oder Problembeschreibung).
const BLOCKIEREND = /zugang|zutritt|schlüssel|einlass|ansprechbar vor ort|problembeschreibung|fehlerbild|was genau|welche(r|s)? (defekt|schaden|problem)|art des (problems|schadens)|unklar/i;
const fehlend = t(a.fehlende_informationen);
const offeneAngaben = /^(keine?|-|–|unbekannt|n\/a)$/i.test(fehlend) ? [] : fehlend.split(/[,;]+/).map(s => s.trim()).filter(Boolean).filter(s => BLOCKIEREND.test(s));
if (cfg.fehlende_angaben_blockieren && offeneAngaben.length) gruende.push('Angaben unvollständig: ' + offeneAngaben.join(', ').slice(0, 120));

const adresse = t(a.adresse);
if (adresse.length < 5 || !/\d/.test(adresse)) gruende.push('Adresse fehlt oder unvollständig');
if (t(a.telefon_normalisiert || a.telefon).replace(/\D/g, '').length < 6) gruende.push('Telefonnummer fehlt');

// Ortsnamen werden vor dem Vergleich auf beiden Seiten vereinheitlicht: Umlaute und ß
// ausgeschrieben, alles außer Buchstaben entfernt. So gilt "Muenchen" = "München",
// während ein echter Hörfehler wie "Mönchen" weiterhin nicht passt.
const ortNorm = v => t(v).toLowerCase()
  .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue').replace(/ß/g, 'ss')
  .replace(/[^a-z]/g, '');
const gebietPlz = ((cfg.einsatzgebiet || {}).plz || []).map(p => t(p)).filter(Boolean);
const gebietOrte = ((cfg.einsatzgebiet || {}).orte || []).map(o => ortNorm(o)).filter(Boolean);
// Die PLZ kommt ausschließlich aus dem eigenen PLZ-Feld und wird nie aus Adresse oder Ort erraten.
const plzEingabe = t(a.plz);
const plz = /^\d{5}$/.test(plzEingabe) ? plzEingabe : '';
if (!plz) gruende.push(plzEingabe ? 'PLZ ungültig (nicht fünfstellig)' : 'PLZ fehlt');
const ort = ortNorm(a.ort);
if (!gebietPlz.length && !gebietOrte.length) gruende.push('Einsatzgebiet nicht konfiguriert');
else if (plz) {
  // Die Begründung nennt das Kriterium, das tatsächlich entschieden hat.
  if (gebietPlz.length) {
    if (!gebietPlz.some(p => plz.startsWith(p))) gruende.push('Außerhalb des Einsatzgebiets (PLZ ' + plz + ')');
  } else if (!(ort && gebietOrte.includes(ort))) {
    gruende.push('Außerhalb des Einsatzgebiets (Ort ' + (t(a.ort) || 'nicht angegeben') + ')');
  }
}

const vorab = (cfg.vorabpruefung_stichworte || []).filter(w => anliegenText.includes(String(w).toLowerCase()));
if (vorab.length) gruende.push('Vorabprüfung, Sonderqualifikation oder Ersatzteile nötig (' + vorab.join(', ') + ')');

const arten = cfg.terminarten || {};
let art = t((gewaehlt && gewaehlt.terminart) || (verschiebung && verschiebung.alt.terminart) || a.terminart);
if (!arten[art]) {
  art = '';
  const treffer = Object.keys(arten).filter(k => (arten[k].stichworte || []).some(w => anliegenText.includes(String(w).toLowerCase())));
  const nichtAuto = treffer.filter(k => !arten[k].automatisch);
  if (nichtAuto.length) art = nichtAuto[0];
  else if (treffer.length) art = treffer.sort((x, y) => (Number(arten[y].dauer_minuten) || 0) - (Number(arten[x].dauer_minuten) || 0))[0];
  else {
    const perKategorie = Object.keys(arten).filter(k => (arten[k].kategorien || []).includes(t(a.kategorie)));
    if (perKategorie.length === 1) art = perKategorie[0];
  }
}
const dauer = art ? Number(arten[art].dauer_minuten) : NaN;
if (!art) gruende.push('Terminart nicht eindeutig erkennbar');
else if (arten[art].automatisch !== true) gruende.push('Terminart „' + (arten[art].bezeichnung || art) + '“ ist nicht zur automatischen Terminvergabe freigegeben');
else if (!(dauer > 0)) gruende.push('Dauer für Terminart „' + art + '“ unbekannt');

if (gruende.length) {
  const antwortAn = ['bestaetigen', 'kundenantwort', 'verschieben', 'verschieben_bestaetigen', 'direkt_buchen'].includes(aktion) && !notfall;
  return [{ json: { weiter: 'mitarbeiter', mitarbeiter: {
    aufgabe_anlegen: Boolean(verschiebung),
    titel: verschiebung ? 'Verschiebungswunsch – bitte persönlich abstimmen' : undefined,
