const nummern = new Set();
for (const m of text.matchAll(/(?<![\d.:])([1-9])(?![\d:]|\.\d|\s*uhr)/g)) { const z = Number(m[1]); if (gueltigeNummern.has(z)) nummern.add(z); }
const woerter = { erste: 1, ersten: 1, erster: 1, eins: 1, zweite: 2, zweiten: 2, zweiter: 2, zwei: 2, dritte: 3, dritten: 3, dritter: 3, drei: 3 };
