} } }];

const tz = $('Terminkonfiguration').first().json.cfg.zeitzone;
const anzeige = s => DateTime.fromISO(String(s), { zone: 'utc' }).setZone(tz).setLocale('de').toFormat("cccc, dd.MM.yyyy 'um' HH:mm 'Uhr'");
const termin = $('Reservierung auswerten').first().json.termin;
const kal = $('Kalendereintrag prüfen').isExecuted ? $('Kalendereintrag prüfen').first().json.externe_event_id : '';
return [{ json: { weiter: 'mitarbeiter', mitarbeiter: {
  aufgabe_anlegen: true,
  titel: 'Kalendereintrag angelegt, Buchung nicht gespeichert – bitte sofort prüfen',
  beschreibung: 'Termin ' + termin.id + ' (' + anzeige(termin.start_at) + ') ist reserviert, Kalendereintrag ' + kal + ' existiert, der Status „gebucht“ konnte nicht gespeichert werden.',
  prioritaet: 'hoch',
  termin_status: 'fehler',
  termin_id: termin.id,
  gruende: ['Buchung konnte nicht gespeichert werden'],
  kunden_nachricht: 'Vielen Dank für Ihre Rückmeldung. Ihr Termin konnte gerade nicht automatisch bestätigt werden. Unser Serviceteam meldet sich persönlich bei Ihnen.'
} } }];

const K = $('Terminkonfiguration').first().json;
const ANTWORT_ERWARTET = ['bestaetigen', 'kundenantwort', 'direkt_buchen', 'verschieben', 'stornieren'];
const x = $input.first().json;
const meldung = String((x.error && (x.error.message || x.error)) || x.message || 'unbekannter Fehler').slice(0, 300);
return [{ json: { weiter: 'mitarbeiter', mitarbeiter: {
  aufgabe_anlegen: true,
  titel: 'Technischer Fehler im Terminassistenten – Termin bitte manuell planen',
  beschreibung: 'Datenbankzugriff fehlgeschlagen: ' + meldung,
  prioritaet: 'hoch',
  termin_status: 'fehler',
  gruende: ['Datenbankfehler'],
  kunden_nachricht: ANTWORT_ERWARTET.includes(K.aktion) ? 'Vielen Dank für Ihre Rückmeldung. Ihr Termin konnte gerade nicht automatisch bestätigt werden. Unser Serviceteam meldet sich persönlich bei Ihnen.' : ''
} } }];

const K = $('Terminkonfiguration').first().json;
const a = K.anfrage || {};
const anfrageOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(a.anfrage_db_id || ''));
const A = (ergebnis, x) => Object.assign({ ergebnis, termin_status: null, mitarbeiter_noetig: false, notfall: false, kunden_nachricht: '', gruende: [], vorschlaege: [], termin: null }, x || {});

if ($runIndex > 0) throw new Error('Mitarbeiterfall mehrfach ausgelöst – Abbruch, um eine Schleife zu verhindern');
const m = $input.first().json.mitarbeiter || {};
const PRIO = ['niedrig', 'normal', 'hoch', 'notfall'];
const status = { termin_status: anfrageOk ? (m.termin_status || null) : null };
if (m.termin_id) status.termin_id = m.termin_id;
const antwort = A(m.ergebnis || 'mitarbeiter', {
  termin_status: status.termin_status, mitarbeiter_noetig: true, notfall: Boolean(m.notfall), kunden_nachricht: m.kunden_nachricht || '',
  gruende: m.gruende || [], termin: m.termin || null, aufgabe_angelegt: false,
  mitarbeiter_info: m.mitarbeiter_info || { betreff: 'Terminassistent: ' + (m.titel || 'Mitarbeiterprüfung nötig'), text: (m.gruende || []).join('; ') }
});
if (m.aufgabe_anlegen && anfrageOk) {
  // Eigene Aufgabe je Anfrage vom Typ termin_pruefen (DB erlaubt nur eine Aufgabe je Anfrage und Typ;
  // die Anfrageprüfung des Hauptworkflows bleibt unverändert). Wiederholte Fälle aktualisieren diese Aufgabe.
  const aufgabe = {
    betrieb_id: K.betrieb_id,
    anfrage_db_id: a.anfrage_db_id,
    typ: 'termin_pruefen',
    titel: ('Terminassistent: ' + (m.titel || 'Termin manuell planen')).slice(0, 200),
    beschreibung: ('Anfrage ' + (a.anfrage_id || a.anfrage_db_id) + ' (' + K.kanal + ') – ' + (m.gruende || []).join('; ') + (m.beschreibung ? '. ' + m.beschreibung : '') + ' (Stand ' + new Date().toISOString() + ')').slice(0, 2000),
    prioritaet: PRIO.includes(m.prioritaet) ? m.prioritaet : 'normal',
    status: 'offen',
    freigabe_erforderlich: true,
    termin_status: m.termin_status || 'mitarbeiterpruefung',
    termin_id: m.termin_id || null
  };
  antwort.aufgabe_angelegt = true;
  return [{ json: { weiter: 'aufgabe_anlegen', aufgabe, status, antwort } }];
}
if (status.termin_status) return [{ json: { weiter: 'status_schreiben', status, antwort } }];
return [{ json: { weiter: 'antwort', antwort } }];

// Upsert auf (anfrage_db_id, typ): 201 = neu angelegt, 200/204 = bestehende Terminaufgabe aktualisiert.
const r = $input.first().json;
const M = $('Mitarbeiterfall vorbereiten').first().json;
if (![200, 201, 204].includes(r.statusCode)) {
  const code = r.body && r.body.code ? ', ' + r.body.code : '';
  throw new Error('Mitarbeiteraufgabe konnte nicht angelegt werden (HTTP ' + r.statusCode + code + ')');
}
return [{ json: { weiter: 'status_schreiben', status: M.status, antwort: M.antwort } }];

// Terminstatus an Anfrage und zugehörigen Aufgaben – erst danach geht eine Antwort zurück.
const K = $('Terminkonfiguration').first().json;
const a = K.anfrage || {};
const anfrageOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(a.anfrage_db_id || ''));
const x = $input.first().json;
const s = x.status || {};
if (!anfrageOk || (!s.termin_status && !s.zuruecksetzen)) return [{ json: { weiter: 'antwort', antwort: x.antwort } }];
const body = s.zuruecksetzen
  ? { termin_status: null, termin_id: null, updated_at: new Date().toISOString() }
  : Object.assign({ termin_status: s.termin_status, updated_at: new Date().toISOString() }, s.termin_id ? { termin_id: s.termin_id } : {});
return ['anfragen', 'aufgaben'].map(tabelle => ({ json: {
  weiter: 'status_patch',
  tabelle,
  url: K.supabase_url + '/rest/v1/' + tabelle + '?' + (tabelle === 'anfragen' ? 'id' : 'anfrage_db_id') + '=eq.' + a.anfrage_db_id + '&betrieb_id=eq.' + K.betrieb_id,
  body,
  antwort: x.antwort
} }));

const erwartet = $('Terminstatus vorbereiten').all();
const r = $input.all();
if (r.length !== erwartet.length || r.some(i => !(i.json.statusCode >= 200 && i.json.statusCode < 300))) {
  throw new Error('Terminstatus konnte nicht vollständig gespeichert werden');
}
return [{ json: { weiter: 'antwort', antwort: erwartet[0].json.antwort } }];

// Einheitliche, kanalneutrale Rückgabe – mit Leitplanke gegen Preise/Diagnosen.
const x = ($input.first().json.antwort) || {};
const K = $('Terminkonfiguration').first().json;
const gruende = Array.isArray(x.gruende) ? x.gruende.filter(Boolean) : [];
let text = String(x.kunden_nachricht || '');
let mitarbeiter = Boolean(x.mitarbeiter_noetig);
const PREIS = /\d+([.,]\d+)?\s*(€|eur\b|euro)|\bkosten|\bpreis|\bgünstig|\bkostenlos|\bgratis|\bpauschale/i;
const DIAGNOSE = /\bdiagnose\b|ursache ist|liegt (wahrscheinlich|vermutlich) an|\bist defekt\b/i;
if (text && (PREIS.test(text) || DIAGNOSE.test(text))) {
  gruende.push('Kundennachricht wegen Preis- oder Diagnoseinhalt zurückgehalten');
  text = '';
  mitarbeiter = true;
}
return [{ json: {
  ergebnis: x.ergebnis || 'fehler',
  aktion: K.aktion || null,
  kanal: K.kanal || null,
  termin_status: x.termin_status ?? null,
  mitarbeiter_noetig: mitarbeiter,
  notfall: Boolean(x.notfall),
  kunden_nachricht: text,
  vorschau_nachricht: x.vorschau_nachricht || '',
  gruende,
  vorschlaege: Array.isArray(x.vorschlaege) ? x.vorschlaege : [],
  termin: x.termin || null,
  aufgabe_angelegt: Boolean(x.aufgabe_angelegt),
  mitarbeiter_info: x.mitarbeiter_info || null,
  modus: K.cfg ? K.cfg.modus : null
} }];

// Einziger Einstieg für Kalenderänderungen (Anlegen/Löschen). Folgeschritte für Erfolg und Fehler reisen mit.
const k = $input.first().json.kalender || {};
if (!['anlegen', 'loeschen'].includes(k.op)) throw new Error('Kalenderaktion ungültig');
if (!k.bei_erfolg || !k.bei_fehler) throw new Error('Kalenderaktion ohne Folgeschritt');
if (k.op === 'loeschen' && !k.event_id) throw new Error('Kalenderaktion: Eintrags-ID fehlt');
return [{ json: { op: k.op, event_id: k.event_id || null, termin: k.termin || {}, bei_erfolg: k.bei_erfolg, bei_fehler: k.bei_fehler } }];

// Test-Kalender: simuliert Anlegen/Löschen, schreibt nirgendwohin. Liefert wie ein echter Kalender nur das Ergebnis.
const t = $('Terminkonfiguration').first().json.test || {};
const R = $('Kalenderaktion anfordern').first().json;
if (R.op === 'anlegen') {
  if (t.kalender_fehler_aenderung) return [{ json: { quelle: 'testkalender', fehler: 'Testkalender nicht erreichbar (simuliert)' } }];
  return [{ json: { quelle: 'testkalender', id: 'TEST-' + R.termin.id + '-' + Date.now() } }];
}
if (t.kalender_fehler_loeschen) return [{ json: { quelle: 'testkalender', fehler: 'Testkalender nicht erreichbar (simuliert)' } }];
return [{ json: { quelle: 'testkalender', geloescht: R.event_id } }];

const cfg = $('Terminkonfiguration').first().json.cfg;
const R = $('Kalenderaktion anfordern').first().json;
const x = $input.first().json;
let eventId = null;
if (cfg.kalender.anbieter === 'test') {
  if (x.quelle !== 'testkalender' || x.fehler) throw new Error(x.fehler || 'Testkalender: keine Antwort');
  if (R.op === 'anlegen') {
    if (!x.id) throw new Error('Testkalender: kein Eintrag angelegt');
    eventId = String(x.id);
  } else if (x.geloescht !== R.event_id) {
    throw new Error('Testkalender: Eintrag nicht gelöscht');
  }
} else if (R.op === 'anlegen') {
  if (!x.id || !x.iCalUId) throw new Error('Outlook-Termin wurde nicht angelegt');
  eventId = String(x.id);
} else if (x.statusCode !== 204) {
  throw new Error('Outlook-Termin wurde nicht gelöscht');
}
return [{ json: Object.assign({}, R.bei_erfolg, { kalender_ergebnis: { op: R.op, event_id: eventId || R.event_id } }) }];

// Kalenderfehler: vorbereiteten sicheren Folgeschritt ausführen (kein Terminversprechen an den Kunden).
const R = $('Kalenderaktion anfordern').first().json;
const x = $input.first().json;
const meldung = String((x.error && (x.error.message || x.error)) || x.message || 'Kalender nicht erreichbar').slice(0, 200);
const f = JSON.parse(JSON.stringify(R.bei_fehler));
if (f.mitarbeiter) f.mitarbeiter.beschreibung = [f.mitarbeiter.beschreibung, 'Kalendermeldung: ' + meldung].filter(Boolean).join(' ');
return [{ json: Object.assign(f, { kalender_fehler: meldung }) }];

const K = $('Terminkonfiguration').first().json;
const cfg = K.cfg;
const tz = cfg.zeitzone;
const utc = s => DateTime.fromISO(String(s), { zone: 'utc' });
const anzeige = s => utc(s).setZone(tz).setLocale('de').toFormat("cccc, dd.MM.yyyy 'um' HH:mm 'Uhr'");
const ok2xx = r => r && r.statusCode >= 200 && r.statusCode < 300;

// Die Verschiebung ist ein einziges Update der bestehenden Buchung: entweder vollständig oder gar nicht.
const P = $('Kalenderaktion prüfen').first().json;
const v = P.verschiebung;
const alt = v.alt;
const neuEvent = P.kalender_ergebnis.event_id;
const r = $input.first().json;
const zeilen = Array.isArray(r.body) ? r.body : [];
const code = r.body && !Array.isArray(r.body) ? String(r.body.code || '') : '';
if (ok2xx(r) && zeilen.length === 1 && zeilen[0].id === alt.id && zeilen[0].status === 'gebucht' && utc(zeilen[0].start_at).toMillis() === utc(v.neu.start_at).toMillis()) {
  const erfolg = { weiter: 'verschieben_historie', verschoben: zeilen[0], alt, alter_eintrag_geloescht: true };
  if (!alt.externe_event_id) return [{ json: erfolg }];
  return [{ json: { weiter: 'kalender_aktion', kalender: { op: 'loeschen', event_id: alt.externe_event_id, termin: alt,
    bei_erfolg: erfolg, bei_fehler: Object.assign({}, erfolg, { alter_eintrag_geloescht: false }) } } }];
}
const grund = code === '23P01' ? 'Neuer Termin überschneidet sich inzwischen mit einer anderen Buchung'
  : code === '23505' ? 'Neuer Termin von der Datenbank abgelehnt (Doppelbuchung)'
  : (ok2xx(r) ? 'Bisheriger Termin war nicht mehr gebucht' : 'Verschiebung konnte nicht gespeichert werden (HTTP ' + (r.statusCode || '–') + ')');
const kunde = 'Vielen Dank für Ihre Rückmeldung. Der gewählte neue Termin ist leider nicht mehr verfügbar. Ihr bisheriger Termin am ' + anzeige(alt.start_at) + ' bleibt bestehen. Unser Serviceteam meldet sich persönlich.';
const ma = (hoch, zusatz) => ({ weiter: 'mitarbeiter', mitarbeiter: {
  aufgabe_anlegen: true, titel: 'Verschiebung nicht durchgeführt – bitte abstimmen',
  beschreibung: grund + '. Bisheriger Termin bleibt: ' + anzeige(alt.start_at) + '. Gewünscht: ' + anzeige(v.neu.start_at) + '.' + (zusatz || ''),
  prioritaet: hoch ? 'hoch' : 'normal', termin_status: 'gebucht', termin_id: alt.id, gruende: [grund], kunden_nachricht: kunde
} });
return [{ json: { weiter: 'kalender_aktion', kalender: { op: 'loeschen', event_id: neuEvent, termin: { id: alt.id },
  bei_erfolg: ma(false), bei_fehler: ma(true, ' Achtung: neuer Kalendereintrag ' + neuEvent + ' konnte nicht entfernt werden – bitte manuell löschen.') } } }];

// Nachvollziehbarkeit: der bisherige Termin wird als Verlaufszeile (status storniert) festgehalten.
const x = $input.first().json;
const alt = x.alt, neu = x.verschoben;
if (!alt || !neu) throw new Error('Verschiebung: Daten fehlen');
const geloescht = x.alter_eintrag_geloescht === true && !x.kalender_fehler;
return [{ json: { alt, neu, alter_eintrag_geloescht: geloescht, historie: {
  betrieb_id: alt.betrieb_id, anfrage_db_id: alt.anfrage_db_id, terminart: alt.terminart, ressource_id: alt.ressource_id, kalender_anbieter: alt.kalender_anbieter,
  status: 'storniert', kunden_bestaetigung: 'bestaetigt', start_at: alt.start_at, ende_at: alt.ende_at,
  puffer_vor_minuten: alt.puffer_vor_minuten, puffer_nach_minuten: alt.puffer_nach_minuten, belegt_von: alt.belegt_von, belegt_bis: alt.belegt_bis,
  zeitzone: alt.zeitzone, vorschlag_gruppe: 'HISTORIE-VERSCHIEBUNG', fehler_code: 'VERSCHOBEN',
  fehler_text: ('Verschoben auf ' + neu.start_at + ' (Termin-ID ' + neu.id + ') am ' + new Date().toISOString() + '; alter Kalendereintrag ' + (alt.externe_event_id || '–') + (geloescht ? ' gelöscht' : ' NICHT gelöscht')).slice(0, 500),
  bestaetigt_at: alt.bestaetigt_at, gebucht_at: alt.gebucht_at
} } }];

const K = $('Terminkonfiguration').first().json;
const cfg = K.cfg;
const tz = cfg.zeitzone;
const a = K.anfrage || {};
const utc = s => DateTime.fromISO(String(s), { zone: 'utc' });
const anzeige = s => utc(s).setZone(tz).setLocale('de').toFormat("cccc, dd.MM.yyyy 'um' HH:mm 'Uhr'");
const terminInfo = z => ({ termin_id: z.id, start_utc: utc(z.start_at).toISO(), ende_utc: utc(z.ende_at).toISO(), anzeige: anzeige(z.start_at), terminart: z.terminart, status: z.status });
const A = (ergebnis, x) => Object.assign({ ergebnis, termin_status: null, mitarbeiter_noetig: false, notfall: false, kunden_nachricht: '', gruende: [], vorschlaege: [], termin: null }, x || {});
const info = (betreff, zeilen) => ({ betreff, text: zeilen.filter(Boolean).join('\n') });

const V = $('Verschiebung protokollieren vorbereiten').first().json;
const r = $input.first().json;
const historieOk = Boolean(r && r.statusCode === 201);
const neu = V.neu, alt = V.alt;
const E = $('Eignung prüfen').first().json;
const nachricht = 'Ihr Termin wurde verschoben. Neuer Termin: ' + anzeige(neu.start_at) + ' (' + E.terminart_bezeichnung + '). Der bisherige Termin am ' + anzeige(alt.start_at) + ' entfällt.';
const mitarbeiter_info = info('Termin verschoben: ' + anzeige(alt.start_at) + ' → ' + anzeige(neu.start_at), [
  'Anfrage: ' + (a.anfrage_id || a.anfrage_db_id), 'Kanal: ' + K.kanal, 'Termin-ID: ' + neu.id,
  V.alter_eintrag_geloescht ? '' : 'Achtung: alter Kalendereintrag wurde nicht gelöscht',
  historieOk ? '' : 'Hinweis: Verlaufszeile konnte nicht gespeichert werden'
]);
if (!V.alter_eintrag_geloescht || !historieOk) {
  return [{ json: { weiter: 'mitarbeiter', mitarbeiter: {
    ergebnis: 'verschoben', termin: terminInfo(neu), mitarbeiter_info,
    aufgabe_anlegen: true, titel: 'Termin verschoben – bitte Kalender/Verlauf prüfen', beschreibung: mitarbeiter_info.text.replace(/\n/g, '; '),
    prioritaet: 'normal', termin_status: 'gebucht', termin_id: neu.id,
    gruende: [V.alter_eintrag_geloescht ? 'Verlaufszeile fehlt' : 'Alter Kalendereintrag nicht gelöscht'], kunden_nachricht: nachricht
  } } }];
}
return [{ json: { weiter: 'status_schreiben', status: { termin_status: 'gebucht', termin_id: neu.id },
  antwort: A('verschoben', { termin_status: 'gebucht', termin: terminInfo(neu), kunden_nachricht: nachricht, mitarbeiter_info }) } }];

const K = $('Terminkonfiguration').first().json;
const cfg = K.cfg;
const tz = cfg.zeitzone;
const a = K.anfrage || {};
const utc = s => DateTime.fromISO(String(s), { zone: 'utc' });
const anzeige = s => utc(s).setZone(tz).setLocale('de').toFormat("cccc, dd.MM.yyyy 'um' HH:mm 'Uhr'");
const terminInfo = z => ({ termin_id: z.id, start_utc: utc(z.start_at).toISO(), ende_utc: utc(z.ende_at).toISO(), anzeige: anzeige(z.start_at), terminart: z.terminart, status: z.status });
const A = (ergebnis, x) => Object.assign({ ergebnis, termin_status: null, mitarbeiter_noetig: false, notfall: false, kunden_nachricht: '', gruende: [], vorschlaege: [], termin: null }, x || {});
const ok2xx = r => r && r.statusCode >= 200 && r.statusCode < 300;
const info = (betreff, zeilen) => ({ betreff, text: zeilen.filter(Boolean).join('\n') });

const t = $('Terminwahl erkennen').first().json.storno_termin;
const r = $input.first().json;
const zeilen = Array.isArray(r.body) ? r.body : [];
const kalenderGeloescht = $('Kalenderaktion prüfen').isExecuted;
if (ok2xx(r) && zeilen.length === 1 && zeilen[0].status === 'storniert') {
  const mitarbeiter_info = info('Termin storniert: ' + anzeige(t.start_at), ['Anfrage: ' + (a.anfrage_id || a.anfrage_db_id), 'Kanal: ' + K.kanal, 'Termin-ID: ' + t.id]);
  return [{ json: { weiter: 'status_schreiben', status: { zuruecksetzen: true },
    antwort: A('storniert', { termin: terminInfo(zeilen[0]), mitarbeiter_info,
      kunden_nachricht: 'Ihr Termin am ' + anzeige(t.start_at) + ' wurde storniert. Wenn Sie einen neuen Termin wünschen, antworten Sie gerne auf diese Nachricht.' }) } }];
}
return [{ json: { weiter: 'mitarbeiter', mitarbeiter: {
  aufgabe_anlegen: true, titel: 'Stornierung nicht vollständig – bitte prüfen',
  beschreibung: 'Termin ' + t.id + ' (' + anzeige(t.start_at) + '): Kalendereintrag ' + (kalenderGeloescht ? 'gelöscht' : 'unverändert') + ', Status „storniert“ nicht gespeichert (HTTP ' + (r.statusCode || '–') + ').',
  prioritaet: 'hoch', termin_status: 'fehler', termin_id: t.id, gruende: ['Stornierung konnte nicht gespeichert werden'],
  kunden_nachricht: 'Vielen Dank, Ihr Stornierungswunsch ist eingegangen. Die Stornierung konnte gerade nicht automatisch abgeschlossen werden; unser Serviceteam meldet sich persönlich bei Ihnen.'
} } }];

// Reservierungen, die länger als die Ablaufzeit nicht gebucht wurden, dürfen keine Termine dauerhaft blockieren.
// Automatisch freigegeben wird nur eindeutig: andere Anfrage, Status „reserviert“, älter als die Ablaufzeit,
// kein verknüpfter Kalendereintrag und kein Kalendereintrag im Terminzeitraum. Alles andere bleibt blockiert
// und geht an die Mitarbeiterprüfung. Kalendereinträge werden hier nie gelöscht.
const K = $('Terminkonfiguration').first().json;
const utc = s => DateTime.fromISO(String(s), { zone: 'utc' });
const ms = s => utc(s).toMillis();
const ueberlappt = (a1, a2, b1, b2) => a1 < b2 && b1 < a2;
const x = $input.first().json;
const grenze = utc(K.jetzt_utc).minus({ minutes: Number(K.cfg.reservierung_ablauf_minuten) });
const eigene = String((K.anfrage || {}).anfrage_db_id || '');
const sicher = [], unsicher = [];
for (const r of x.db_belegt) {
  if (r.status !== 'reserviert' || r.anfrage_db_id === eigene) continue;
  const stand = utc(r.updated_at);
  if (!stand.isValid || stand >= grenze) continue;
  const kalender = x.kalender_belegt.some(k => ueberlappt(ms(k.von_utc), ms(k.bis_utc), ms(r.start_at), ms(r.ende_at)));
  (r.externe_event_id || kalender ? unsicher : sicher).push(r);
}
const daten = { kalender_belegt: x.kalender_belegt, db_belegt: x.db_belegt };
if (!sicher.length && !unsicher.length) return [{ json: Object.assign({ weiter: 'termine_berechnen' }, daten) }];
return [{ json: Object.assign({ weiter: 'reservierungen_freigeben', grenze_utc: grenze.toISO(), sicher, unsicher }, daten) }];

// Nur tatsächlich freigegebene Zeilen blockieren nicht mehr. Jede Freigabe und jeder unsichere Fall
// bekommt eine Mitarbeiteraufgabe an der betroffenen Anfrage. Nicht freigegebene Zeilen blockieren weiter.
const K = $('Terminkonfiguration').first().json;
const tz = K.cfg.zeitzone;
const anzeige = s => DateTime.fromISO(String(s), { zone: 'utc' }).setZone(tz).setLocale('de').toFormat("cccc, dd.MM.yyyy 'um' HH:mm 'Uhr'");
const P = $('Abgelaufene Reservierungen prüfen').first().json;
const r = $input.first().json;
const ok = r.statusCode >= 200 && r.statusCode < 300 && Array.isArray(r.body);
const freigegeben = ok ? r.body.filter(z => z.status === 'abgelaufen').map(z => z.id) : [];
const minuten = K.cfg.reservierung_ablauf_minuten;
const stand = ' (Stand ' + new Date().toISOString() + ')';
const aufgabe = (z, titel, text) => ({
  betrieb_id: K.betrieb_id, anfrage_db_id: z.anfrage_db_id, typ: 'termin_pruefen',
  titel: 'Terminassistent: ' + titel, beschreibung: (text + stand).slice(0, 2000),
  prioritaet: 'hoch', status: 'offen', freigabe_erforderlich: true, termin_status: 'mitarbeiterpruefung', termin_id: z.id
});
const aufgaben = [];
for (const z of P.sicher.filter(z => freigegeben.includes(z.id))) {
  aufgaben.push(aufgabe(z, 'Reservierung abgelaufen und freigegeben – Kunde bitte kontaktieren',
    'Termin ' + z.id + ' (' + anzeige(z.start_at) + ') war länger als ' + minuten + ' Minuten reserviert, ohne Buchung und ohne Kalendereintrag. Er wurde automatisch freigegeben (Status „abgelaufen“). Der Kunde hat keine Buchungsbestätigung erhalten.'));
}
for (const z of P.unsicher) {
  aufgaben.push(aufgabe(z, 'Abgelaufene Reservierung mit möglichem Kalendereintrag – bitte prüfen',
    'Termin ' + z.id + ' (' + anzeige(z.start_at) + ') ist länger als ' + minuten + ' Minuten reserviert und nicht gebucht, aber ' + (z.externe_event_id ? 'ein Kalendereintrag ist verknüpft' : 'im selben Zeitraum steht ein Kalendereintrag') + '. Keine automatische Änderung: Der Termin bleibt blockiert, Kalender und Buchung bitte manuell prüfen.'));
}
const eindeutig = [...new Map(aufgaben.map(a => [a.anfrage_db_id, a])).values()];
const daten = {
  kalender_belegt: P.kalender_belegt,
  db_belegt: P.db_belegt.filter(z => !freigegeben.includes(z.id)),
  freigabe: { freigegeben, unsicher: P.unsicher.map(z => z.id), nicht_freigegeben: P.sicher.filter(z => !freigegeben.includes(z.id)).map(z => z.id), http_status: r.statusCode }
};
if (!eindeutig.length) return [{ json: Object.assign({ weiter: 'termine_berechnen' }, daten) }];
return [{ json: Object.assign({ weiter: 'freigabe_aufgaben', aufgaben: eindeutig, anfragen_ids: eindeutig.map(a => a.anfrage_db_id) }, daten) }];

// Aufgaben und Anfragestatus sind der Nachweis der Freigabe. Scheitern sie, bleibt die Freigabe am Termin selbst
// (Status, fehler_code, fehler_text) nachvollziehbar; unsichere Fälle werden beim nächsten Lauf erneut gemeldet.
const F = $('Freigabe auswerten').first().json;
const ok = x => Boolean(x) && x.statusCode >= 200 && x.statusCode < 300;
const aufgaben = $('Freigabe: Mitarbeiteraufgaben anlegen').first().json;
const anfragen = $input.first().json;
return [{ json: { weiter: 'termine_berechnen', kalender_belegt: F.kalender_belegt, db_belegt: F.db_belegt,
  freigabe: Object.assign({}, F.freigabe, { aufgaben_gespeichert: ok(aufgaben), anfragestatus_gespeichert: ok(anfragen) }) } }];

// Erst wenn die abgelehnten Vorschläge gespeichert sind, geht es weiter – sonst könnten sie erneut angeboten werden.
const W = $('Terminwahl erkennen').first().json;
const r = $input.first().json;
if (!(r.statusCode >= 200 && r.statusCode < 300) || !Array.isArray(r.body) || r.body.length !== W.ablehnung_ids.length) {
  throw new Error('Ablehnung der Terminvorschläge konnte nicht gespeichert werden (HTTP ' + r.statusCode + ')');
}
return [{ json: W.danach }];
